    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    // ------------------------------------------------------------------
    // Schedule for initialization:
    //  - Row-major traversal (j = x, i = y)
    //  - Vectorize along j (innermost dimension)
    //  - Parallelize along i (outer dimension)
    // ------------------------------------------------------------------
