    // B(i,j) in C -> B(j,i) in Halide
    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    // Obtain a reasonable native vector width for the host CPU
    Target target = get_host_target();
    int vec = target.natural_vector_size<num_t>();
    if (vec < 1) vec = 1;

    // Schedule for init_A: tile over (j,i), vectorize j (innermost),
    // and parallelize over outer tiles in the i-dimension.
    init_A
        .tile(j, i, jo, io, ji, ii, INIT_TILE_X, INIT_TILE_Y)
        .vectorize(ji, vec)
        .parallel(io);

