 *       A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *       B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
 *     }
 *
 * We map A[i][j] -> A(j, i) and B[i][j] -> B(j, i) in Halide.
 *
 * This version adds a cache-friendly, vectorized, and parallel schedule.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // n as a Halide Expr, with the correct element type.
    Expr n_expr = cast<num_t>(Expr(n));

    // A(i,j) in C -> A(j,i) in Halide
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / n_expr;
    // B(i,j) in C -> B(j,i) in Halide
    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    // -------------------------------
    // Schedule for initialization
    // -------------------------------
    //
    // We want:
    //  - x/j (dimension 0) as the fast axis (already true for Buffer)
    //  - vectorization along j (contiguous in memory)
    //  - parallelization across tiles of i (rows)
    //
    // The tile sizes are compile-time constants that can be tuned for
    // a given machine; they aim to fit tiles comfortably in L1/L2.
    const int tile_x = 128;  // columns per tile (must be multiple of SIMD width for best perf)
    const int tile_y = 32;   // rows   per tile

    // Pick a natural SIMD width for this target and element type.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size<num_t>();

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    // Both init_A and init_B traverse the domain in the same way,
    // but are separate Funcs so they can be compiled independently.
    init_A
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    init_B
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    // Realize into the user-provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n       = N;
    int tsteps  = TSTEPS;

    // Buffers corresponding to A[N][N] and B[N][N].
    // C layout is A[i][j]; we map that to A_buf(j, i).
    Halide::Buffer<num_t, 2> A(n, n);  // x = j, y = i
    Halide::Buffer<num_t, 2> B(n, n);  // x = j, y = i

    // Initialize A and B (optimized Halide schedule inside).
    init_array(n, A, B);

